    pin("green gunners, a swarm attack (seed 3): a draw at the 120 s limit -- three fighters shot down, five still flying (two hurt), the ship at 1,302 and the wave-motion cannon fired once", BS.fight(3, "swarm", { gunners: "green" }), { winner: "none", over: "time", ticks: 3600, killed: 3, rammed: 0, damageOnShip: 198, hpLeft: 1302, seatRounds: 1124, shipHits: 840, waves: 1, partsOut: "", fighters: "destroyed/0/2/36 flying/60/1/18 destroyed/0/0/0 flying/60/3/54 destroyed/0/3/54 flying/45/0/0 flying/100/0/0 flying/65/2/36" });
