    pin("the shipped pilot against GREEN gunners, a swarm (seed 1): the SHIP is lost at 58 s with three fighters shot down and five flying", BS.fight(1, "swarm", { gunners: "green", pilot: SHIPPED }), { winner: "fighters", over: "one team left flying", ticks: 1748, killed: 3, rammed: 0, damageOnShip: 1500, hpLeft: 0, seatRounds: 841, shipHits: 770, waves: 1, partsOut: "", fighters: "flying/50/7/126 flying/50/13/234 destroyed/0/7/126 flying/90/17/306 flying/50/10/180 flying/90/7/126 destroyed/0/11/198 destroyed/0/12/216" });
    pin("the league pilot as the fighters, regular gunners, a swarm (seed 2): the ship wins at 25.6 s having lost 306", BS.fight(2, "swarm", { pilot: LEAGUE }), { winner: "ship", over: "one team left flying", ticks: 769, killed: 8, rammed: 0, damageOnShip: 306, hpLeft: 1194, seatRounds: 756, shipHits: 1100, waves: 1, partsOut: "", fighters: "destroyed/0/3/36 destroyed/0/1/18 destroyed/0/2/18 destroyed/0/3/36 destroyed/0/3/36 destroyed/0/2/36 destroyed/0/3/36 destroyed/0/5/90" });
    pin("sixteen shipped-pilot fighters against regular gunners, a bow attack (seed 1): the SHIP is destroyed at 15.8 s with one fighter shot down", BS.fight(1, "bow", { fighters: 16, pilot: SHIPPED }), { winner: "fighters", over: "one team left flying", ticks: 474, killed: 1, rammed: 0, damageOnShip: 1500, hpLeft: 0, seatRounds: 405, shipHits: 510, waves: 1 });
    const tot = (a, f) => a.reduce((x, t) => x + f(t), 0);
    const sweep = (o) => { const rows = []; for (const k of ["bow", "swarm"]) for (let s = 1; s <= 6; s++) rows.push(BS.fight(s, k, o)); return { n: rows.length, killed: tot(rows, (t) => t.killed), shipWins: rows.filter((t) => t.winner === "ship").length, fightersWin: rows.filter((t) => t.winner === "fighters").length, none: rows.filter((t) => t.winner === "none").length, dmg: tot(rows, (t) => t.damageOnShip), partsOut: tot(rows, (t) => t.ship.partsOut.length), rounds: tot(rows, (t) => t.ship.seatRounds), waves: tot(rows, (t) => t.ship.waves) }; };
    const S = { pdPerfect: sweep({ gunners: "perfect" }), pdRegular: sweep({}), pdGreen: sweep({ gunners: "green" }), shRegular: sweep({ pilot: SHIPPED }), shGreen: sweep({ gunners: "green", pilot: SHIPPED }), leRegular: sweep({ pilot: LEAGUE }), clRegular: sweep({ pilot: CLOSE }), sh12: sweep({ pilot: SHIPPED, fighters: 12 }) };
