    ok("!! ...by GREEN gunners: they CANNOT CLEAR THE SKY -- 37 of 96 shot down, all twelve fights run out the 120 s clock (a draw: the PD fighters do not beat the ship either, 1,944 damage in all)", same(S.pdGreen, { killed: 37, shipWins: 0, fightersWin: 0, none: 12, dmg: 1944, partsOut: 0, rounds: 11892, waves: 14 }), line(S.pdGreen));
    ok("!! THE TRAINED FIGHTERS ARE THE THREAT THE PD AUTOPILOT IS NOT: the shipped 6DOF pilot's eight against REGULAR gunners put 14,796 damage on the ship over 12 attacks where the PD pilot's put 1,692 (8.7 times) -- and the ship still wins all twelve (96 shot down); the league pilot 3,960 (the ship wins 11, one drawn)", same(S.shRegular, { killed: 96, shipWins: 12, fightersWin: 0, none: 0, dmg: 14796, partsOut: 2, rounds: 8905, waves: 7 }) && same(S.leRegular, { killed: 95, shipWins: 11, fightersWin: 0, none: 1, dmg: 3960, partsOut: 0, rounds: 9248, waves: 7 }) && S.shRegular.dmg > 8 * S.pdRegular.dmg, `${line(S.shRegular)} | ${line(S.leRegular)}`);
    ok("!! against GREEN gunners the shipped pilot's eight BEAT the ship five times in twelve (the ship is destroyed, 28 fighters shot down in all, 17,328 damage), and twelve of them beat it EVERY TIME against regular gunners (25 shot down in all, 18,000 damage: twelve ships of 1,500)", same(S.shGreen, { killed: 28, shipWins: 0, fightersWin: 5, none: 7, dmg: 17328, partsOut: 7, rounds: 9780, waves: 14 }) && same(S.sh12, { killed: 25, shipWins: 0, fightersWin: 12, none: 0, dmg: 18000, partsOut: 3, rounds: 5676, waves: 5 }), `${line(S.shGreen)} | ${line(S.sh12)}`);
    ok("!! SAID PLAINLY: the CLOSE-QUARTERS pilot does the ship NO damage in this world (0 in twelve attacks, the ship wins all twelve) -- it was trained to fight at 14-40 units and the doctrine asks it to open fire from 220 -- it is a finding about the pilot and the doctrine, not a bug the gate excuses", same(S.clRegular, { killed: 96, shipWins: 12, fightersWin: 0, none: 0, dmg: 0, partsOut: 0, rounds: 11342, waves: 8 }), line(S.clRegular));
    ok("!! the skill order holds for the PD fighters: more of them are shot down by perfect and regular gunners than by green ones, and the ship is never lost to them; and the trained pilot only beats the ship when it is gunned green or outnumbers it", S.pdPerfect.killed >= S.pdRegular.killed && S.pdRegular.killed > S.pdGreen.killed && S.pdPerfect.fightersWin === 0 && S.pdRegular.fightersWin === 0 && S.pdGreen.fightersWin === 0 && S.shRegular.fightersWin === 0 && S.shGreen.fightersWin > 0 && S.sh12.fightersWin === 12);
    const again = BS.fight(3, "swarm", { gunners: "green" }), ar = BS.build(3, "swarm", { gunners: "green" }).arena; while (!ar.done) SA.stepSpaceArena(ar);
    ok("!! a fight is deterministic: flown twice it is the same tally, and fight() is build() stepped by hand and summed with tally()", JSON.stringify(again) === JSON.stringify(BS.fight(3, "swarm", { gunners: "green" })) && JSON.stringify(again) === JSON.stringify(BS.tally(ar)));
    const mid = BS.build(1, "bow").arena; for (let i = 0; i < 30; i++) SA.stepSpaceArena(mid); const m = BS.tally(mid);
